node -e '
const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const code = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]).join("\n;\n");
eval(code);
const { Sim } = globalThis.__DSP_CORE__;

// 1. flash crowd → rate limiting + shed + queue pressure, then recovery
let s = new Sim(20260, "flash-crowd");
s.step(7000);
const mid = s.snapshot();
s.step(23000);
const end = s.snapshot();
console.log("flash-crowd @7s: rateLimited=" + mid.metrics.rateLimited, "shed=" + mid.metrics.shed, "depth=" + mid.queue.depth, "state=" + mid.state);
console.log("flash-crowd @30s: depth=" + end.queue.depth, "state=" + end.state, "completed=" + end.metrics.completed);

// 2. database outage → breaker opens, retries accumulate, recovery drains
s = new Sim(777, "database-outage");
s.step(7000);
const b1 = s.snapshot();
s.step(23000);
const b2 = s.snapshot();
console.log("outage @7s: breaker=" + b1.breaker.state, "retryPending=" + b1.retry.pending.length, "commits=" + b1.primary.commits);
console.log("outage @30s: breaker=" + b2.breaker.state, "primaryUp=" + b2.primary.up, "commits=" + b2.primary.commits, "retryPending=" + b2.retry.pending.length, "dlq=" + b2.dlq.length);

// 3. more workers drain a backlog faster
const backlog = (n) => { const x = new Sim(5, "healthy"); x.setTraffic(0,"T"); x.setWorkers(n,"T"); for (let i=0;i<30;i++) x.schedule(i*20, ()=>x.injectRequest({op:"write"})); x.step(6000); return x.queue.items.length + " depth / " + x.metrics.completed + " done"; };
console.log("workers=2 after 6s:", backlog(2), "| workers=10:", backlog(10));

// 4. lower gateway capacity throttles intake
const gw = (rate) => { const x = new Sim(9, "healthy"); x.setGatewayRate(rate,"T"); x.setTraffic(20,"T"); x.step(8000); return "accepted=" + x.gateway.accepted + " rejected=" + x.gateway.rejected; };
console.log("gateway 6/s:", gw(6), "| gateway 40/s:", gw(40));

// 5. duplicate burst prevents exactly 5
s = new Sim(3, "healthy"); s.setTraffic(0,"T"); s.cfg.writeFailRate = 0;
s.sendDuplicateBurst(); s.step(15000);
console.log("dup burst: commits=" + s.primary.commits, "duplicatesPrevented=" + s.metrics.duplicatesPrevented);

// 6. stale replica scenario produces stale reads then converges
s = new Sim(4242, "stale-replica"); s.step(9000);
const st1 = s.metrics.staleReads; s.step(6000);
console.log("stale-replica: staleReads@9s=" + st1, "behind@15s=" + (s.primary.log.length - s.replica.applyIndex), "replicaLag=" + s.cfg.replicaLag);

// 7. poison scenario end-to-end via public ops
s = new Sim(99, "poison-message"); s.step(22000);
console.log("poison scenario: dlq=" + s.dlq.items.length, s.dlq.items.map(d=>d.reqId+":"+d.reason).join(","));
const pid = s.dlq.items[0] && s.dlq.items[0].reqId;
if (pid) { s.repairDeadLetter(pid); s.replayDeadLetter(pid); s.step(6000);
  console.log("after repair+replay: state=" + s.requests.get(pid).state, "outcome=" + s.requests.get(pid).outcome); }
'

