dev-browser --headless --timeout 90 <<'EOF'
const page = await browser.getPage("dsp");
const out = {};

// deterministic reset via the live app: same seed + same steps → identical snapshots
out.determinism = await page.evaluate(() => {
  window.__DSP__.reset(424242);
  window.__DSP__.step(5000);
  const a = JSON.stringify(window.__DSP__.snapshot());
  window.__DSP__.reset(424242);
  window.__DSP__.step(5000);
  const b = JSON.stringify(window.__DSP__.snapshot());
  return a === b;
});

// pause + UI step button advances exactly 50 ms
out.stepButton = await page.evaluate(() => {
  const t0 = window.__DSP__.snapshot().time;
  document.getElementById("btn-step").click();
  const t1 = window.__DSP__.snapshot().time;
  document.getElementById("btn-step").click();
  const t2 = window.__DSP__.snapshot().time;
  return { d1: t1 - t0, d2: t2 - t1 };
});

// scenario switching via buttons
out.scenarioButtons = await page.evaluate(() => {
  const btn = [...document.querySelectorAll(".scn")].find(b => b.dataset.scn === "database-outage");
  btn.click();
  const s = window.__DSP__.snapshot();
  return { scenario: s.scenario, seed: s.seed, pressed: btn.getAttribute("aria-pressed") };
});

// fault injection: fail primary → breaker opens under write load; recover → closes
out.outageFlow = await page.evaluate(() => {
  window.__DSP__.setScenario("healthy");
  window.__DSP__.pause();
  document.getElementById("sl-traffic").value = 12;
  document.getElementById("sl-traffic").dispatchEvent(new Event("input"));
  document.getElementById("btn-db").click();          // fail primary
  window.__DSP__.step(6000);
  const during = window.__DSP__.snapshot();
  document.getElementById("btn-db").click();          // recover
  window.__DSP__.step(12000);
  const after = window.__DSP__.snapshot();
  return {
    duringBreaker: during.breaker.state, duringCommits: during.primary.commits, duringRetries: during.retry.pending.length,
    afterBreaker: after.breaker.state, afterCommits: after.primary.commits, dbBtn: document.getElementById("btn-db").textContent,
    stateChipDuring: during.state,
  };
});

// worker stop/restore + lag buttons
out.faultButtons = await page.evaluate(() => {
  document.getElementById("btn-worker").click();
  window.__DSP__.step(200);
  const stopped = window.__DSP__.snapshot().workers.filter(w => w.stopped).length;
  const label = document.getElementById("btn-worker").textContent;
  document.getElementById("btn-worker").click();
  window.__DSP__.step(200);
  const restored = window.__DSP__.snapshot().workers.filter(w => w.stopped).length;
  document.getElementById("btn-lag").click();
  const lag = window.__DSP__.snapshot().replica.lagMs;
  document.getElementById("btn-lag").click();
  const lagCleared = window.__DSP__.snapshot().replica.lagMs;
  return { stopped, label, restored, lag, lagCleared };
});
console.log(JSON.stringify(out, null, 2));
EOF

