dev-browser --headless --timeout 90 <<'EOF'
const page = await browser.getPage("dsp");
const out = {};

// poison scenario end-to-end through the real UI
out.poison = await page.evaluate(async () => {
  window.__DSP__.setScenario("poison-message");
  window.__DSP__.pause();
  window.__DSP__.step(22000); // enough for 5 attempts + backoffs
  const snap1 = window.__DSP__.snapshot();
  await new Promise(r => requestAnimationFrame(r)); // let the DLQ panel render
  const repairBtn = document.querySelector('#dlq-list [data-act="repair"]');
  const replayBtn = document.querySelector('#dlq-list [data-act="replay"]');
  if (!repairBtn || !replayBtn) return { fail: "no DLQ buttons", dlq: snap1.dlq };
  const rid = repairBtn.dataset.rid;
  repairBtn.click();
  replayBtn.click();
  window.__DSP__.step(6000);
  const snap2 = window.__DSP__.snapshot();
  return { dlqBefore: snap1.dlq.length, reason: snap1.dlq[0] && snap1.dlq[0].reason,
           dlqAfter: snap2.dlq.length, commits: snap2.primary.commits, rid };
});

// duplicate burst via button
out.dupes = await page.evaluate(() => {
  window.__DSP__.setScenario("healthy");
  window.__DSP__.pause();
  document.getElementById("sl-traffic").value = 0;
  document.getElementById("sl-traffic").dispatchEvent(new Event("input"));
  document.getElementById("btn-dupes").click();
  window.__DSP__.step(15000);
  const s = window.__DSP__.snapshot();
  return { commits: s.primary.commits, dupesPrevented: s.metrics.duplicatesPrevented };
});

// inspector via log request-id click
out.inspector = await page.evaluate(async () => {
  document.getElementById("btn-one").click();
  window.__DSP__.step(3000);
  await new Promise(r => requestAnimationFrame(r));
  const rid = document.querySelector("#log-list .rid");
  if (!rid) return { fail: "no rid in log" };
  rid.click();
  await new Promise(r => requestAnimationFrame(r));
  const body = document.getElementById("insp-body").textContent;
  return { id: document.getElementById("insp-id").textContent,
           hasLifecycle: body.includes("response delivered") || body.includes("attempt"), chars: body.length };
});

// stored-records view via primary node click + log filters
out.records = await page.evaluate(async () => {
  document.querySelector('[data-node="primary"]').dispatchEvent(new MouseEvent("click", { bubbles: true }));
  await new Promise(r => requestAnimationFrame(r));
  const txt = document.getElementById("insp-body").textContent;
  document.querySelector('[data-lf="err"]').click();
  const errRows = document.getElementById("log-list").children.length;
  document.querySelector('[data-lf="all"]').click();
  const allRows = document.getElementById("log-list").children.length;
  return { recordsView: txt.includes("PRIMARY RECORDS") || txt.includes("primary"), errRows, allRows };
});

// packet click selection
out.packetClick = await page.evaluate(async () => {
  window.__DSP__.play();
  await new Promise(r => setTimeout(r, 700));
  window.__DSP__.pause();
  await new Promise(r => requestAnimationFrame(r));
  const pk = document.querySelector("#board-packets .packet");
  if (!pk) return { fail: "no packet on board" };
  pk.dispatchEvent(new MouseEvent("click", { bubbles: true }));
  await new Promise(r => requestAnimationFrame(r));
  return { selected: document.getElementById("insp-id").textContent, rid: pk.dataset.rid };
});
console.log(JSON.stringify(out, null, 2));
EOF

