out.keyboard = await page.evaluate(async () => {
  window.__DSP__.pause();
  document.body.focus();
  document.dispatchEvent(new KeyboardEvent("keydown", { key: " ", bubbles: true, cancelable: true }));
  const t0 = window.__DSP__.snapshot().time;
  await new Promise(r => setTimeout(r, 400));
  const t1 = window.__DSP__.snapshot().time;
  document.dispatchEvent(new KeyboardEvent("keydown", { key: " ", bubbles: true, cancelable: true }));
  const t2 = window.__DSP__.snapshot().time;
  await new Promise(r => setTimeout(r, 300));
  const t3 = window.__DSP__.snapshot().time;
  return { advancedWhilePlaying: t1 > t0, frozenWhilePaused: t3 === t2 };
});
console.log(JSON.stringify(out, null, 2));
EOF

